class WordProcessor:
    def __init__(self, textContent):
        self.textContent = textContent

    def toLowercase(self):
        return self.textContent.lower()

class PunctuationRemover:
    def __init__(self, processedText):
        self.processedText = processedText

    def removeAll(self):
        return ''.join(char for char in self.processedText if char.isalnum() or char.isspace())

class WordSplitter:
    def __init__(self, cleanText):
        self.cleanText = cleanText

    def splitIntoWords(self):
        return self.cleanText.split()

class FrequencyCounter:
    def __init__(self):
        self.wordCounts = {}

    def updateCounts(self, wordList):
        for word in wordList:
            self.wordCounts[word] = self.wordCounts.get(word, 0) + 1
        return self.wordCounts

class ResultFormatter:
    def __init__(self, finalCounts):
        self.finalCounts = finalCounts

    def getFormattedResult(self):
        return self.finalCounts

def word_frequency(text):
    textProcessor = WordProcessor(text)
    lowercaseText = textProcessor.toLowercase()

    cleaner = PunctuationRemover(lowercaseText)
    cleanedText = cleaner.removeAll()

    splitter = WordSplitter(cleanedText)
    wordList = splitter.splitIntoWords()

    counter = FrequencyCounter()
    finalCounts = counter.updateCounts(wordList)

    formatter = ResultFormatter(finalCounts)
    return formatter.getFormattedResult()

