        self.values = values

class AverageCalculator:
    def calculate(self, number_list):
        if not number_list.values:
            return 0.0
        total_sum = SumAggregator().aggregate(number_list.values)
        item_counter = ItemCounter().count(number_list.values)
        return total_sum / item_counter

