class CaesarCipher:
    def __init__(self, textToEncrypt, shiftAmount):
        self.originalText = textToEncrypt
        self.cipherShift = shiftAmount

    def getEncryptedText(self):
        return ''.join(CharacterProcessor.processCharacter(char, self.cipherShift) for char in self.originalText)

class CharacterProcessor:
    @staticmethod
    def processCharacter(charToProcess, currentShift):
        if 'a' <= charToProcess <= 'z':
            return CharacterShifter.applyShift(charToProcess, 'a', currentShift)
        elif 'A' <= charToProcess <= 'Z':
            return CharacterShifter.applyShift(charToProcess, 'A', currentShift)
        else:
            return charToProcess

class CharacterShifter:
    @staticmethod
    def applyShift(baseChar, alphabetStart, shiftValue):
        alphabetPosition = ord(baseChar) - ord(alphabetStart)
        shiftedPosition = (alphabetPosition + shiftValue) % 26
        return chr(ord(alphabetStart) + shiftedPosition)

class EncryptionService:
    @staticmethod
    def performEncryption(inputString, shiftFactor):
        cipherTool = CaesarCipher(inputString, shiftFactor)
        return cipherTool.getEncryptedText()

