import random
import string

class CharacterSet:
    def __init__(self, chars):
        self.characterPool = chars

    def getRandomCharacter(self):
        return random.choice(self.characterPool)

class PasswordGenerator:
    def __init__(self):
        self.lowerCaseChars = CharacterSet(string.ascii_lowercase)
        self.upperCaseChars = CharacterSet(string.ascii_uppercase)
        self.digitChars = CharacterSet(string.digits)
        self.allCharacterSets = [self.lowerCaseChars, self.upperCaseChars, self.digitChars]

    def generatePassword(self, length):
        if length <= 0:
            raise ValueError("Password length must be positive.")

        passwordCharacters = []
        for _ in range(length):
            randomCharSet = random.choice(self.allCharacterSets)
            passwordCharacters.append(randomCharSet.getRandomCharacter())
        return "".join(passwordCharacters)

class PasswordLengthValidator:
    def isValid(self, length):
        return length > 0

class PasswordManager:
    def __init__(self):
        self.generator = PasswordGenerator()
        self.validator = PasswordLengthValidator()

    def createNewPassword(self, length):
        if not self.validator.isValid(length):
            raise ValueError("Invalid password length provided.")
        return self.generator.generatePassword(length)

class PasswordResult:
    def __init__(self, passwordString):
        self.password = passwordString
        self.length = len(passwordString)

def generate_password(length):
    passwordManager = PasswordManager()
    generatedPassword = passwordManager.createNewPassword(length)
    passwordResult = PasswordResult(generatedPassword)
    return passwordResult.password

