class YearDivisibility:
    def __init__(self, year_value):
        self.year_value = year_value

    def is_divisible_by(self, divisor):
        return self.year_value % divisor == 0

class LeapYearCriteria:
    def __init__(self, year_value):
        self.year_divisibility = YearDivisibility(year_value)

    def meets_basic_rule(self):
        return self.year_divisibility.is_divisible_by(4)

    def meets_century_exception(self):
        return not self.year_divisibility.is_divisible_by(100)

    def meets_quadricentennial_rule(self):
        return self.year_divisibility.is_divisible_by(400)

class YearClassifier:
    def __init__(self, year_value):
        self.leap_criteria = LeapYearCriteria(year_value)

    def is_leap_year(self):
        meets_basic = self.leap_criteria.meets_basic_rule()
        meets_century = self.leap_criteria.meets_century_exception()
        meets_quad = self.leap_criteria.meets_quadricentennial_rule()
        return (meets_basic and meets_century) or meets_quad

class YearValidator:
    def __init__(self, year_data):
        self.year_classifier = YearClassifier(year_data)

    def check_year(self):
        return self.year_classifier.is_leap_year()

