class WordTokenizer:
    def __init__(self, textString):
        self.rawText = textString
    def get_tokens(self):
        return self.rawText.split(' ')

class WordReverser:
    def __init__(self, tokenList):
        self.originalTokens = tokenList
    def get_reversed_tokens(self):
        return self.originalTokens[::-1]

class SentenceAssembler:
    def __init__(self, tokenList):
        self.tokenSequence = tokenList
    def get_assembled_sentence(self):
        return ' '.join(self.tokenSequence)

class SentenceProcessor:
    def __init__(self, inputSentence):
        self.inputSentence = inputSentence
    def process_sentence(self):
        tokenizer = WordTokenizer(self.inputSentence)
        wordTokens = tokenizer.get_tokens()
        reverser = WordReverser(wordTokens)
        reversedTokens = reverser.get_reversed_tokens()
        assembler = SentenceAssembler(reversedTokens)
        return assembler.get_assembled_sentence()

class StringManipulator:
    def reverse_words(self, sentence):
        processor = SentenceProcessor(sentence)
        return processor.process_sentence()

def reverse_words(sentence):
