class CharacterCounter:
    def __init__(self, char, count):
        self.char = char
        self.count = count

    def to_string(self):
        return f"{self.char}{self.count}"

class EncodedSequence:
    def __init__(self):
        self.items = []

    def add_item(self, item):
        self.items.append(item)

    def to_string(self):
        return "".join(item.to_string() for item in self.items)

class CurrentRun:
    def __init__(self, char):
        self.character = char
        self.count = 1

    def increment(self):
        self.count += 1

class RunProcessor:
    def process(self, char_run, encoded_result):
        char_count = CharacterCounter(char_run.character, char_run.count)
        encoded_result.add_item(char_count)

class StringEncoder:
    def encode(self, input_string):
        if not input_string:
            return ""

        encoded_result = EncodedSequence()
        processor = RunProcessor()
        current_run = CurrentRun(input_string[0])

        for i in range(1, len(input_string)):
            if input_string[i] == current_run.character:
                current_run.increment()
            else:
                processor.process(current_run, encoded_result)
                current_run = CurrentRun(input_string[i])

        processor.process(current_run, encoded_result)
        return encoded_result.to_string()

def run_length_encode(s: str) -> str:
    encoder = StringEncoder()
    return encoder.encode(s)

