class BinaryConverter:
    def convert_decimal_to_binary(self, decimal_number):
        if decimal_number == 0:
            return "0"
        binary_digits = []
        current_number = decimal_number
        while current_number > 0:
            remainder_value = current_number % 2
            binary_digits.append(str(remainder_value))
            current_number //= 2
        return "".join(reversed(binary_digits))

class InputValidator:
    def is_valid_input(self, value_to_check):
        return isinstance(value_to_check, int) and value_to_check >= 0

class ResultFormatter:
    def format_output(self, binary_string):
        return binary_string

class OperationHandler:
    def perform_conversion(self, decimal_input):
        validator_instance = InputValidator()
        if not validator_instance.is_valid_input(decimal_input):
            raise ValueError("Input must be a non-negative integer.")
        converter_instance = BinaryConverter()
        binary_result = converter_instance.convert_decimal_to_binary(decimal_input)
        formatter_instance = ResultFormatter()
        return formatter_instance.format_output(binary_result)

def decimal_to_binary(decimal_int):
    handler_instance = OperationHandler()
    return handler_instance.perform_conversion(decimal_int)

