class ParenthesisPair:
    def __init__(self, open_char, close_char):
        self.openChar = open_char
        self.closeChar = close_char

class ParenthesisMatcher:
    def __init__(self):
        self.mapping = {
            ')': ParenthesisPair('(', ')'),
            '}': ParenthesisPair('{', '}'),
            ']': ParenthesisPair('[', ']')
        }
        self.openChars = set([p.openChar for p in self.mapping.values()])

class BracketStack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop() if not self.is_empty() else None

    def is_empty(self):
        return len(self.items) == 0

    def peek(self):
        return self.items[-1] if not self.is_empty() else None

class SolutionChecker:
    def is_valid_parentheses(self, s: str) -> bool:
        bracket_stack = BracketStack()
        parenthesis_matcher = ParenthesisMatcher()

        for char in s:
            if char in parenthesis_matcher.openChars:
                bracket_stack.push(char)
            elif char in parenthesis_matcher.mapping:
                if bracket_stack.is_empty() or bracket_stack.pop() != parenthesis_matcher.mapping[char].openChar:
                    return False
            else:
                return False # Unexpected character

        return bracket_stack.is_empty()

def is_valid_parentheses(s: str) -> bool:
    checker = SolutionChecker()
    return checker.is_valid_parentheses(s)

