import math

class NumberCollection:
    def __init__(self, numbers):
        self.rawNumbers = numbers

class MeanCalculator:
    def __init__(self, numbers):
        self.dataPoints = numbers

    def calculateMean(self):
        return sum(self.dataPoints) / len(self.dataPoints)

class SumOfSquares:
    def __init__(self, numbers, mean_value):
        self.numberList = numbers
        self.averageValue = mean_value

    def calculateSum(self):
        return sum([(x - self.averageValue) ** 2 for x in self.numberList])

class VarianceCalculator:
    def __init__(self, sum_sq, count):
        self.totalSquared = sum_sq
        self.dataCount = count

    def calculateSampleVariance(self):
        return self.totalSquared / (self.dataCount - 1)

class StdDevResult:
    def __init__(self, variance_value):
        self.calculatedVariance = variance_value

    def getStandardDeviation(self):
        return math.sqrt(self.calculatedVariance)

def calculate_std_dev(numbers):
    data_points = NumberCollection(numbers)
    mean_obj = MeanCalculator(data_points.rawNumbers)
    mean_value = mean_obj.calculateMean()
    sum_squares_obj = SumOfSquares(data_points.rawNumbers, mean_value)
    sum_sq_value = sum_squares_obj.calculateSum()
    variance_obj = VarianceCalculator(sum_sq_value, len(data_points.rawNumbers))
    variance_value = variance_obj.calculateSampleVariance()
    std_dev_obj = StdDevResult(variance_value)
    return std_dev_obj.getStandardDeviation()

