class RomanSymbol:
    def __init__(self, symbol_char, symbol_value):
        self.symbolChar = symbol_char
        self.symbolValue = symbol_value

class RomanNumeralConverter:
    def __init__(self):
        self.symbolMapping = {
            'I': RomanSymbol('I', 1), 'V': RomanSymbol('V', 5), 'X': RomanSymbol('X', 10),
            'L': RomanSymbol('L', 50), 'C': RomanSymbol('C', 100), 'D': RomanSymbol('D', 500),
            'M': RomanSymbol('M', 1000)
        }

    def convert_single_symbol(self, symbol_char):
        roman_symbol = self.symbolMapping.get(symbol_char)
        if roman_symbol:
            return roman_symbol.symbolValue
        return 0

class RomanStringProcessor:
    def __init__(self, converter_instance):
        self.converterInstance = converter_instance

    def process(self, roman_string):
        total_value = 0
        previous_value = 0
        for char_item in reversed(roman_string):
            current_value = self.converterInstance.convert_single_symbol(char_item)
            if current_value < previous_value:
                total_value -= current_value
            else:
                total_value += current_value
            previous_value = current_value
        return total_value

class SolutionRunner:
    def __init__(self):
        self.converter = RomanNumeralConverter()
        self.processor = RomanStringProcessor(self.converter)

    def run_conversion(self, roman_numeral_string):
        return self.processor.process(roman_numeral_string)

def roman_to_int(roman_numeral):
    solution_instance = SolutionRunner()
    return solution_instance.run_conversion(roman_numeral)

