class CharacterCounter:
    def __init__(self, input_string):
        self.char_counts = self._process_string(input_string)

    def _process_string(self, text_input):
        cleaned_string = text_input.replace(' ', '').lower()
        processed_counts = {}
        for char_item in cleaned_string:
            processed_counts[char_item] = processed_counts.get(char_item, 0) + 1
        return processed_counts

class StringProcessor:
    def __init__(self, raw_string):
        self.normalized_string = raw_string.replace(' ', '').lower()

class AnagramChecker:
    def check_equality(self, first_counts, second_counts):
        return first_counts == second_counts

def is_anagram(s1, s2):
    first_processor = StringProcessor(s1)
    second_processor = StringProcessor(s2)

    first_counter = CharacterCounter(first_processor.normalized_string)
    second_counter = CharacterCounter(second_processor.normalized_string)

    equality_evaluator = AnagramChecker()
    comparison_result = equality_evaluator.check_equality(first_counter.char_counts, second_counter.char_counts)

    class FinalResult:
        def __init__(self, value): self.value = value
    result_object = FinalResult(comparison_result)
    return result_object.value

