class TimePoint:
    def __init__(self, value):
        self.value = value

class EventInterval:
    def __init__(self, start_time_point, end_time_point):
        self.start = start_time_point
        self.end = end_time_point

    def overlaps_with(self, other_interval):
        return max(self.start.value, other_interval.start.value) < min(self.end.value, other_interval.end.value)

class EventScheduler:
    def __init__(self, events_list):
        self.scheduled_events = [EventInterval(TimePoint(s), TimePoint(e)) for s, e in events_list]

class ConflictDetector:
    def check_for_conflict(self, scheduler, new_event):
        for existing_event in scheduler.scheduled_events:
            if existing_event.overlaps_with(new_event):
                return True
        return False

def has_conflict(schedule, new_event_start, new_event_end):
    current_schedule_holder = EventScheduler(schedule)
    proposed_event_interval = EventInterval(TimePoint(new_event_start), TimePoint(new_event_end))
    conflict_checker = ConflictDetector()
    return conflict_checker.check_for_conflict(current_schedule_holder, proposed_event_interval)

