class WordSplitter:
    def __init__(self, sentenceText):
        self.sentenceText = sentenceText
    def getWords(self):
        return self.sentenceText.split()

class WordReverser:
    def __init__(self, wordList):
        self.wordList = wordList
    def getReversedWords(self):
        return self.wordList[::-1]

class SentenceJoiner:
    def __init__(self, wordList):
        self.wordList = wordList
    def getJoinedSentence(self):
        return " ".join(self.wordList)

class SentenceProcessor:
    def __init__(self, sentenceInput):
        self.sentenceInput = sentenceInput
    def processSentence(self):
        wordSplitterInstance = WordSplitter(self.sentenceInput)
        individualWords = wordSplitterInstance.getWords()
        wordReverserInstance = WordReverser(individualWords)
        reversedWords = wordReverserInstance.getReversedWords()
        sentenceJoinerInstance = SentenceJoiner(reversedWords)
        return sentenceJoinerInstance.getJoinedSentence()

class SentenceOperation:
    def reverseWords(self, sentence):
        processorInstance = SentenceProcessor(sentence)
        return processorInstance.processSentence()

def reverse_words(sentence):
    operationHandler = SentenceOperation()
    return operationHandler.reverseWords(sentence)

