class FilePathHandler:
    def __init__(self, path):
        self.fullPath = path

class LineCounter:
    def __init__(self):
        self.currentCount = 0

    def increment(self):
        self.currentCount += 1

class FileReader:
    def __init__(self, handler):
        self.fileHandle = open(handler.fullPath, 'r')

    def read_line(self):
        return self.fileHandle.readline()

    def close_file(self):
        self.fileHandle.close()

class LineProcessor:
    def process(self, line, counter):
        if line:
            counter.increment()

class ResultAggregator:
    def aggregate(self, counter):
        return counter.currentCount

def count_file_lines(filepath):
    path_handler = FilePathHandler(filepath)
    line_counter = LineCounter()
    file_reader = FileReader(path_handler)
    line_processor = LineProcessor()

    while True:
        current_line = file_reader.read_line()
        if not current_line:
            break
        line_processor.process(current_line, line_counter)

    file_reader.close_file()
    result_aggregator = ResultAggregator()
    return result_aggregator.aggregate(line_counter)

