        self.shiftValue = shiftValue

class CharacterProcessor:
    def process(self, char, shift):
        if 'a' <= char <= 'z':
            return chr(((ord(char) - ord('a') - shift + 26) % 26) + ord('a'))
        return char

class MessageTranslator:
    def translate(self, text, processor, shift):
        translatedChars = []
        for char in text:
            translatedChars.append(processor.process(char, shift))
        return "".join(translatedChars)

class DecryptionEngine:
    def decrypt(self, encryptedText, cipher):
        processor = CharacterProcessor()
        translator = MessageTranslator()
        return translator.translate(encryptedText, processor, cipher.shiftValue)

