        self.value = value

def decrypt_caesar(text, shift):
    shiftKey = ShiftKey(shift)
    caesarCipher = CaesarCipher(shiftKey.value)
    decryptionEngine = DecryptionEngine()
    return decryptionEngine.decrypt(text, caesarCipher)

