    def compute(self, numbers):
        return sum(numbers) / len(numbers)

class HarmonicMeanProcessor:
    def process(self, reciprocals_mean):
        return 1.0 / reciprocals_mean

class MeanValueRetriever:
    def retrieve(self, final_mean):
        return final_mean

def harmonic_mean(numbers):
    number_collection = NumberCollection(numbers)
    reciprocal_calculator = ReciprocalCalculator()
    reciprocals = [reciprocal_calculator.calculate(val) for val in number_collection.values]
    arithmetic_mean_computer = ArithmeticMeanComputer()
    mean_of_reciprocals = arithmetic_mean_computer.compute(reciprocals)
    harmonic_mean_processor = HarmonicMeanProcessor()
    final_harmonic_mean = harmonic_mean_processor.process(mean_of_reciprocals)
    mean_value_retriever = MeanValueRetriever()
    return mean_value_retriever.retrieve(final_harmonic_mean)

