class StockLevel:
    def __init__(self, item_name, quantity):
        self.itemName = item_name
        self.availableQuantity = quantity

class InventoryItem:
    def __init__(self, name, current_stock):
        self.productName = name
        self.stockCount = current_stock

class StockChecker:
    def __init__(self, inventory_data):
        self.inventoryData = {InventoryItem(k, v).productName: InventoryItem(k, v).stockCount for k, v in inventory_data.items()}

    def get_stock_levels(self, items_to_query):
        result_levels = {}
        for item in items_to_query:
            current_stock = self.inventoryData.get(item, 0)
            result_levels[StockLevel(item, current_stock).itemName] = StockLevel(item, current_stock).availableQuantity
        return result_levels

class ProductRequest:
    def __init__(self, requested_item_list):
        self.requestedItems = requested_item_list

class InventoryManager:
    def check_stock(self, inventory_dict, items_to_check_list):
        current_inventory = StockChecker(inventory_dict)
        query_request = ProductRequest(items_to_check_list)
        return current_inventory.get_stock_levels(query_request.requestedItems)

def check_stock(inventory, items_to_check):
    manager = InventoryManager()
    return manager.check_stock(inventory, items_to_check)

