    def __init__(self, age_years):
        self.age = age_years

class MifflinStJeorFactors:
    MALE_CONSTANT = 5
    FEMALE_CONSTANT = -161

class BmrResult:
    def __init__(self, bmr_value):
        self.bmr = bmr_value

def calculate_bmr(gender_str, weight_kg, height_cm, age_years):
    gender_identity = GenderSpecifier(gender_str)
    body_data = BodyMeasurement(weight_kg, height_cm)
    age_data = AgeCategory(age_years)

    base_bmr = (10 * body_data.weight) + (6.25 * body_data.height) - (5 * age_data.age)

    if gender_identity.gender == 'male':
        final_bmr = base_bmr + MifflinStJeorFactors.MALE_CONSTANT
    else: # female
        final_bmr = base_bmr + MifflinStJeorFactors.FEMALE_CONSTANT

    bmr_output = BmrResult(final_bmr)
    return bmr_output.bmr

