    def __init__(self, value):
        self.divisor = value

class ModuloResult:
    def __init__(self, result):
        self.modResult = result

class DivisibilityRule:
    def __init__(self, divisor):
        self.targetDivisor = divisor

    def check(self, numberToCheck):
        currentModulo = ModuloResult(numberToCheck.inputNumber % self.targetDivisor.divisor)
        return currentModulo.modResult == 0

class OverallResult:
    def __init__(self, finalState):
        self.isDivisible = finalState

def is_divisible_by_3_and_5(number):
    inputVal = DivisibilityCheck(number)

    ruleForThree = DivisibilityRule(DivisorValue(3))
    ruleForFive = DivisibilityRule(DivisorValue(5))

    isDivisibleByThree = ruleForThree.check(inputVal)
    isDivisibleByFive = ruleForFive.check(inputVal)

    finalDecision = OverallResult(isDivisibleByThree and isDivisibleByFive)
    return finalDecision.isDivisible

