        currentModulo = modulo_result(numberToCheck.inputNumber % self.targetDivisor.divisor)
        return currentModulo.modResult == 0

class overall_result:
    def __init__(self, finalState):
        self.isDivisible = finalState

def is_divisible_by_3_and_5(number):
    inputVal = divisibility_check(number)

    ruleForThree = divisibility_rule(divisor_value(3))
    ruleForFive = divisibility_rule(divisor_value(5))

    isDivisibleByThree = ruleForThree.check(inputVal)
    isDivisibleByFive = ruleForFive.check(inputVal)

    finalDecision = overall_result(isDivisibleByThree and isDivisibleByFive)
    return finalDecision.isDivisible

