class MatrixRow:
    def __init__(self, elements):
        self.elements = elements

class MatrixData:
    def __init__(self, rows):
        self.rows = [MatrixRow(row) for row in rows]

class SubtractionOperation:
    def perform(self, val1, val2):
        return val1 - val2

class ResultMatrixBuilder:
    def __init__(self):
        self.result_rows = []

    def add_row(self, row_elements):
        self.result_rows.append(row_elements)

    def get_matrix_data(self):
        return MatrixData(self.result_rows)

def matrix_subtract(matrix1, matrix2):
    operation = SubtractionOperation()
    builder = ResultMatrixBuilder()

    first_matrix = MatrixData(matrix1)
    second_matrix = MatrixData(matrix2)

    for i in range(len(first_matrix.rows)):
        currentRowElements = []
        first_row_item = first_matrix.rows[i]
        second_row_item = second_matrix.rows[i]
        for j in range(len(first_row_item.elements)):
            current_value = operation.perform(first_row_item.elements[j], second_row_item.elements[j])
            currentRowElements.append(current_value)
        builder.add_row(currentRowElements)

    final_matrix_data = builder.get_matrix_data()
    return [row.elements for row in final_matrix_data.rows]

