class NestedItem:
    def __init__(self, keyName, valueContent):
        self.keyName = keyName
        self.valueContent = valueContent

class FlattenedResult:
    def __init__(self):
        self.outputDictionary = {}

class KeyConcatenator:
    def __init__(self, baseKey, separator):
        self.baseKey = baseKey
        self.separator = separator

    def combine(self, subKey):
        return f"{self.baseKey}{self.separator}{subKey}"

class ValueProcessor:
    def process(self, value):
        return value

def flatten_dict(nested_dict, separator):
    resultContainer = FlattenedResult()
    dictFlattener = DictionaryFlattener(separator)

    for outerKey, outerValue in nested_dict.items():
        currentItem = NestedItem(outerKey, outerValue)
        if isinstance(currentItem.valueContent, dict):
            keyJoiner = KeyConcatenator(currentItem.keyName, dictFlattener.separatorString)
            for innerKey, innerValue in currentItem.valueContent.items():
                processedValue = ValueProcessor().process(innerValue)
                resultContainer.outputDictionary[keyJoiner.combine(innerKey)] = processedValue
        else:
            processedValue = ValueProcessor().process(currentItem.valueContent)
            resultContainer.outputDictionary[currentItem.keyName] = processedValue
    return resultContainer.outputDictionary

