class CharacterRepeater:
    def __init__(self, char_to_repeat, repeat_count):
        self.charToRepeat = char_to_repeat
        self.repeatCount = repeat_count

    def generate_string(self):
        return self.charToRepeat * self.repeatCount

class EncodedSegment:
    def __init__(self, count_str, char_str):
        self.countStr = count_str
        self.charStr = char_str

class DecodingProcess:
    def __init__(self, input_string):
        self.inputString = input_string
        self.decodedResult = []

    def perform_decoding(self):
        current_count = ""
        for char_in_input in self.inputString:
            if char_in_input.isdigit():
                current_count += char_in_input
            else:
                segment_info = EncodedSegment(current_count, char_in_input)
                repeater = CharacterRepeater(segment_info.charStr, int(segment_info.countStr))
                self.decodedResult.append(repeater.generate_string())
                current_count = ""
        return "".join(self.decodedResult)

class StringDecoder:
    def __init__(self):
        pass

    def decode(self, encoded_string):
        decoder_instance = DecodingProcess(encoded_string)
        return decoder_instance.perform_decoding()

def run_length_decode(encoded_string):
    main_decoder = StringDecoder()
    return main_decoder.decode(encoded_string)

