class BracketPair:
    def __init__(self, open_bracket, close_bracket):
        self.openBracket = open_bracket
        self.closeBracket = close_bracket

class BracketStack:
    def __init__(self):
        self.items = []

    def pushItem(self, item):
        self.items.append(item)

    def popItem(self):
        return self.items.pop()

    def isEmpty(self):
        return len(self.items) == 0

class BracketValidator:
    def __init__(self):
        self.bracketMap = {
            '(': BracketPair('(', ')'),
            '[': BracketPair('[', ']'),
            '{': BracketPair('{', '}')
        }
        self.openBrackets = set(self.bracketMap.keys())
        self.closeBrackets = set(bp.closeBracket for bp in self.bracketMap.values())

    def validateSequence(self, s):
        stack = BracketStack()
        for char in s:
            if char in self.openBrackets:
                stack.pushItem(char)
            elif char in self.closeBrackets:
                if stack.isEmpty():
                    return False
                last_open = stack.popItem()
                expected_close = self.bracketMap[last_open].closeBracket
                if char != expected_close:
                    return False
        return stack.isEmpty()

class SolutionChecker:
    def checkString(self, input_string):
        validator = BracketValidator()
        return validator.validateSequence(input_string)

def is_brackets_balanced(s):
    checker = SolutionChecker()
    return checker.checkString(s)

