    def process_dates(self, start_str, end_str):
        start_converter = DateConverter(start_str)
        end_converter = DateConverter(end_str)
        start_datetime = start_converter.to_datetime_object()
        end_datetime = end_converter.to_datetime_object()
        calculator = DateDifferenceCalculator()
        return calculator.calculate(start_datetime, end_datetime)

