        processor = DateProcessor()
        validator = DateInputValidator()
        if not validator.is_valid_format(start_date_str) or not validator.is_valid_format(end_date_str):
            raise ValueError("Invalid date format. Expected YYYY-MM-DD.")
        return processor.process_dates(start_date_str, end_date_str)

