class DecimalAccumulator:
    def __init__(self):
        self.total_sum = 0

    def add_term(self, term):
        self.total_sum += term

    def get_total(self):
        return self.total_sum

def hex_to_decimal(hex_string):
    accumulator = DecimalAccumulator()
    string_length = len(hex_string)
    for i, char in enumerate(hex_string):
        digit_value_obj = HexDigitValue(char)
        decimal_digit = digit_value_obj.get_decimal()

        position_obj = DigitPosition(i, string_length)
        power_index = position_obj.get_power_index()

        power_obj = PowerOfSixteen(power_index)
        sixteen_power = power_obj.get_value()

        term_obj = CalculatedTerm(decimal_digit, sixteen_power)
        accumulator.add_term(term_obj.get_term())
    return accumulator.get_total()

