class DigitProcessor:
    def __init__(self, digit_string):
        self.digits = [int(d) for d in digit_string]

class LuhnChecker:
    def __init__(self, digit_processor):
        self.digit_processor = digit_processor

    def calculate_sum(self):
        total_sum = 0
        is_second_digit = False
        for i in range(len(self.digit_processor.digits) - 1, -1, -1):
            current_digit = self.digit_processor.digits[i]
            if is_second_digit:
                doubled_digit = current_digit * 2
                total_sum += doubled_digit if doubled_digit < 10 else doubled_digit - 9
            else:
                total_sum += current_digit
            is_second_digit = not is_second_digit
        return total_sum

