import math

class TwoDimensionalPoint:
    def __init__(self, x_coordinate: float, y_coordinate: float):
        self.x_coordinate = x_coordinate
        self.y_coordinate = y_coordinate

class CoordinatePair:
    def __init__(self, x_val: float, y_val: float):
        self.x_val = x_val
        self.y_val = y_val

class DistanceCalculator:
    def calculate(self, point_one: TwoDimensionalPoint, point_two: TwoDimensionalPoint) -> float:
        delta_x = point_one.x_coordinate - point_two.x_coordinate
        delta_y = point_one.y_coordinate - point_two.y_coordinate
        return math.sqrt(delta_x**2 + delta_y**2)

