    def __init__(self, value: float):
        self.value = value

class DistanceMetric:
    def __init__(self, metric_name: str):
        self.metric_name = metric_name

def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    first_point_coords = CoordinatePair(x1, y1)
    second_point_coords = CoordinatePair(x2, y2)

    point_one = TwoDimensionalPoint(first_point_coords.x_val, first_point_coords.y_val)
    point_two = TwoDimensionalPoint(second_point_coords.x_val, second_point_coords.y_val)

    calculator_instance = DistanceCalculator()
    calculated_distance = calculator_instance.calculate(point_one, point_two)

    result_object = DistanceResult(calculated_distance)
    metric_type = DistanceMetric("Euclidean") 

    return result_object.value

