class WordCounter:
    def __init__(self, raw_text):
        self.rawText = raw_text

    def get_normalized_text(self):
        class CharacterProcessor:
            def process(self, char_input):
                return char_input if char_input.isalnum() else ' '

        normalized_chars = [CharacterProcessor().process(char) for char in self.rawText]
        return ''.join(normalized_chars)

