class RomanDigit:
    def __init__(self, symbol, value):
        self.symbol = symbol
        self.value = value

class RomanNumeralConverter:
    def __init__(self):
        self.symbolValues = {
            'I': 1, 'V': 5, 'X': 10, 'L': 50,
            'C': 100, 'D': 500, 'M': 1000
        }

    def get_value(self, symbol):
        return self.symbolValues[symbol]

class SubtractionRule:
    def __init__(self, smaller, larger):
        self.smaller = smaller
        self.larger = larger

class ConversionResult:
    def __init__(self, value):
        self.value = value

class RomanNumeralProcessor:
    def __init__(self):
        pass

    def process(self, roman_numeral_string):
        converter = RomanNumeralConverter()
        total_value = 0
        previous_value = 0
        for symbol in reversed(roman_numeral_string):
            current_digit = RomanDigit(symbol, converter.get_value(symbol))
            current_value = current_digit.value
            if current_value < previous_value:
                subtraction_rule = SubtractionRule(current_value, previous_value)
                total_value -= subtraction_rule.smaller
            else:
                total_value += current_value
            previous_value = current_value
        final_result = ConversionResult(total_value)
        return final_result.value

def roman_to_int(roman_numeral):
    processor = RomanNumeralProcessor()
    return processor.process(roman_numeral)

