class PrimeContainer:
    def __init__(self):
        self.primes = []

class LoopControl:
    def __init__(self, limit):
        self.limit = limit

def generate_primes(n):
    prime_collection = PrimeContainer()
    if n < 2:
        return prime_collection.primes

    for num_val in range(2, n + 1):
        current_candidate = PrimeCandidate(num_val)
        is_prime_flag = True
        control_loop = LoopControl(int(current_candidate.value**0.5) + 1)
        for divisor_val in range(2, control_loop.limit):
            current_divisor = DivisorEvaluator(divisor_val)
            if current_candidate.value % current_divisor.value == 0:
                is_prime_flag = False
                break
        if is_prime_flag:
            prime_collection.primes.append(current_candidate.value)
    return prime_collection.primes

