    total_value = DecimalAccumulator()

    for index, char_digit in enumerate(reversed(binary_string)):
        current_digit = BinaryDigit(char_digit)
        power_exponent = PowerOfTwo(index)
        weighted_term = PositionWeight(current_digit, power_exponent)
        total_value.add_value(weighted_term.weightedValue)

    final_output = ConversionResult(total_value.currentSum)
    return final_output.decimalValue

