class CharacterCount:
    def __init__(self):
        self.count = 0
        self.first_occurrence_index = -1

class CharacterTracker:
    def __init__(self):
        self.char_map = {}

    def track_character(self, char_value, current_index):
        if char_value not in self.char_map:
            self.char_map[char_value] = CharacterCount()
            self.char_map[char_value].first_occurrence_index = current_index
        self.char_map[char_value].count += 1

class UniqueFinder:
    def __init__(self, input_string):
        self.input_string = input_string
        self.tracker = CharacterTracker()

    def find_index(self):
        for index, char_value in enumerate(self.input_string):
            self.tracker.track_character(char_value, index)

        min_index = float('inf')
        found_unique = False

        for char_value in self.tracker.char_map:
            char_data = self.tracker.char_map[char_value]
            if char_data.count == 1:
                min_index = min(min_index, char_data.first_occurrence_index)
                found_unique = True

        return min_index if found_unique else -1

class SolutionExecutor:
    def execute(self, s: str) -> int:
        finder_instance = UniqueFinder(s)
        return finder_instance.find_index()

def first_unique_char(s: str) -> int:
    executor = SolutionExecutor()
    return executor.execute(s)

