class ConversionFactor:
    METER_TO_FEET = 3.28084

class UnitConverter:
    def __init__(self, from_value: float):
        self.initialValue = from_value

    def to_feet(self) -> float:
        return self.initialValue * ConversionFactor.METER_TO_FEET

    def to_meters(self) -> float:
        return self.initialValue / ConversionFactor.METER_TO_FEET

class LengthUnit:
    METER = 'm'
    FEET = 'ft'

class ConversionDirection:
    METER_TO_FEET = (LengthUnit.METER, LengthUnit.FEET)
    FEET_TO_METER = (LengthUnit.FEET, LengthUnit.METER)

class ConversionResult:
    def __init__(self, converted_value: float):
        self.finalValue = converted_value

    def get_value(self) -> float:
        return self.finalValue

def convert_length(value: float, from_unit: str, to_unit: str) -> float:
    initial_measurement = UnitConverter(value)

    if (from_unit, to_unit) == ConversionDirection.METER_TO_FEET:
        converted_output = ConversionResult(initial_measurement.to_feet())
    elif (from_unit, to_unit) == ConversionDirection.FEET_TO_METER:
        converted_output = ConversionResult(initial_measurement.to_meters())
    else:
        converted_output = ConversionResult(value) # Same units, no conversion

    return converted_output.get_value()

# Example Usage:
# result1 = convert_length(10, 'm', 'ft')
# result2 = convert_length(3.28084, 'ft', 'm')
