class OrderItem:
    def __init__(self, price):
        self.basePrice = price

class PercentageDiscount:
    def __init__(self, percentage):
        self.discountRate = percentage

class PriceCalculator:
    def calculate(self, item, discount):
        discountAmount = item.basePrice * (discount.discountRate / 100)
        return item.basePrice - discountAmount

