    def __init__(self, value):
        self.finalValue = value

class DiscountEngine:
    def applyDiscount(self, originalPrice, discountPercentage):
        anOrderItem = OrderItem(originalPrice)
        aPercentageDiscount = PercentageDiscount(discountPercentage)
        aPriceCalculator = PriceCalculator()
        calculatedPrice = aPriceCalculator.calculate(anOrderItem, aPercentageDiscount)
        aFinalPrice = FinalPrice(calculatedPrice)
        return aFinalPrice.finalValue

def calculate_discount_price(original_price, discount_percentage):
    aDiscountEngine = DiscountEngine()
    return aDiscountEngine.applyDiscount(original_price, discount_percentage)

