        self.value = value

class ExponentValue:
    def __init__(self, value):
        self.value = value

class PowerCalculator:
    def calculate_power(self, base_object, exponent_object):
        base = base_object.value
        exponent = exponent_object.value
        if not isinstance(exponent, int):
            raise TypeError("Exponent must be an integer.")
        return base ** exponent

class CalculationResult:
    def __init__(self, value):
        self.value = value

class DisplayOutput:
    def show_result(self, result_object):
        print(f"The calculated power is: {result_object.value}")

def calculate_power(base, exponent):
    base_instance = BaseNumber(base)
    exponent_instance = ExponentValue(exponent)
    calculator_instance = PowerCalculator()
    raw_result = calculator_instance.calculate_power(base_instance, exponent_instance)
    result_instance = CalculationResult(raw_result)
    output_display = DisplayOutput()
    output_display.show_result(result_instance)
    return result_instance.value

