class TransactionResult:
    def __init__(self, successStatus, newBalance):
        self.successStatus = successStatus
        self.newBalance = newBalance

class InsufficientFunds:
    def __init__(self, requiredAmount, currentAmount):
        self.requiredAmount = requiredAmount
        self.currentAmount = currentAmount

class TransactionRecord:
    def __init__(self, transactionType, amount):
        self.transactionType = transactionType
        self.amount = amount

class BankAccount:
    def __init__(self, initialBalance):
        self.currentBalance = initialBalance
        self.transactionHistory = []

    def deposit(self, amount):
        if amount <= 0:
            return TransactionResult(False, self.currentBalance)
        self.currentBalance += amount
        self.transactionHistory.append(TransactionRecord("Deposit", amount))
        return TransactionResult(True, self.currentBalance)

    def withdraw(self, amount):
        if amount <= 0 or amount > self.currentBalance:
            if amount > self.currentBalance:
                self.lastError = InsufficientFunds(amount, self.currentBalance)
            return TransactionResult(False, self.currentBalance)
        self.currentBalance -= amount
        self.transactionHistory.append(TransactionRecord("Withdrawal", amount))
        return TransactionResult(True, self.currentBalance)

class AccountManager:
    def __init__(self):
        self.accounts = {}

    def createAccount(self, accountId, initialBalance):
        newAccount = BankAccount(initialBalance)
        self.accounts[accountId] = newAccount
        return newAccount

