import math

class TriangleSide:
    def __init__(self, length):
        self.length = length

class TrianglePerimeter:
    def __init__(self, s1, s2, s3):
        self.s1 = s1
        self.s2 = s2
        self.s3 = s3
        self.half_perimeter = (s1 + s2 + s3) / 2.0

class TriangleValidityChecker:
    def __init__(self, side_a, side_b, side_c):
        self.side_a = side_a
        self.side_b = side_b
        self.side_c = side_c

    def is_valid(self):
        return (self.side_a + self.side_b > self.side_c and
                self.side_a + self.side_c > self.side_b and
                self.side_b + self.side_c > self.side_a)

class TriangleAreaCalculator:
    def calculate(self, s_perimeter, side_a, side_b, side_c):
        return math.sqrt(s_perimeter * (s_perimeter - side_a) *
                         (s_perimeter - side_b) * (s_perimeter - side_c))

class OutputFormatter:
    def format(self, value):
        return float(value)

def triangle_area(a, b, c):
    side_one = TriangleSide(a)
    side_two = TriangleSide(b)
    side_three = TriangleSide(c)

    validity_check = TriangleValidityChecker(side_one.length, side_two.length, side_three.length)
    if not validity_check.is_valid():
        return 0.0

    perimeter_data = TrianglePerimeter(side_one.length, side_two.length, side_three.length)
    area_calc = TriangleAreaCalculator()
    raw_area = area_calc.calculate(perimeter_data.half_perimeter,
                                   side_one.length, side_two.length, side_three.length)

    formatter = OutputFormatter()
    return formatter.format(raw_area)

