class MatrixCell:
    def __init__(self, value):
        self.cellValue = value

class MatrixRow:
    def __init__(self, size):
        self.rowCells = [MatrixCell(0) for _ in range(size)]

class DistanceMatrix:
    def __init__(self, rows, cols):
        self.matrixRows = [MatrixRow(cols) for _ in range(rows)]

    def get_value(self, r, c):
        return self.matrixRows[r].rowCells[c].cellValue

    def set_value(self, r, c, value):
        self.matrixRows[r].rowCells[c].cellValue = value

class EditOperation:
    INSERTION = 1
    DELETION = 1
    SUBSTITUTION = 1

def levenshtein_distance(s1, s2):
    len1, len2 = len(s1), len(s2)
    distanceGrid = DistanceMatrix(len1 + 1, len2 + 1)

    for i in range(len1 + 1):
        distanceGrid.set_value(i, 0, i * EditOperation.DELETION)
    for j in range(len2 + 1):
        distanceGrid.set_value(0, j, j * EditOperation.INSERTION)

    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else EditOperation.SUBSTITUTION
            insert = distanceGrid.get_value(i, j - 1) + EditOperation.INSERTION
            delete = distanceGrid.get_value(i - 1, j) + EditOperation.DELETION
            substitute = distanceGrid.get_value(i - 1, j - 1) + cost
            distanceGrid.set_value(i, j, min(insert, delete, substitute))

    finalResult = distanceGrid.get_value(len1, len2)
    return finalResult

