class DigitMapper:
    def __init__(self):
        self.digitMap = "0123456789ABCDEF"

    def get_char(self, value):
        return self.digitMap[value]

class NumberConverter:
    def __init__(self, decimalNumber, targetBase):
        self.decimalNumber = decimalNumber
        self.targetBase = targetBase
        self.digitMapper = DigitMapper()

    def convert_to_string(self):
        if self.decimalNumber == 0:
            return "0"

        resultDigits = []
        currentNumber = self.decimalNumber

        while currentNumber > 0:
            remainder = currentNumber % self.targetBase
            digitChar = self.digitMapper.get_char(remainder)
            resultDigits.append(digitChar)
            currentNumber //= self.targetBase

        return "".join(resultDigits[::-1])

class BaseConversionResult:
    def __init__(self, originalNumber, targetBase, convertedString):
        self.originalNumber = originalNumber
        self.targetBase = targetBase
        self.convertedString = convertedString

    def get_result(self):
        return self.convertedString

class InputValidator:
    def validate(self, number, base):
        if not isinstance(number, int) or number < 0:
            raise ValueError("Number must be a non-negative integer.")
        if not isinstance(base, int) or not (2 <= base <= 16):
            raise ValueError("Base must be an integer between 2 and 16.")
        return True

class ConversionProcess:
    def execute(self, number, base):
        validator = InputValidator()
        validator.validate(number, base)

        converter = NumberConverter(number, base)
        converted_string = converter.convert_to_string()

        result = BaseConversionResult(number, base, converted_string)
        return result.get_result()

def convert_base(number, base):
    process = ConversionProcess()
    return process.execute(number, base)

