class TemperatureConverter:
    def __init__(self):
        pass

    def convert_temperature(self, value, unit_from, unit_to):
        initial_value_wrapper = InitialValue(value)
        from_unit_wrapper = TemperatureUnit(unit_from)
        to_unit_wrapper = TemperatureUnit(unit_to)

        if from_unit_wrapper.unit_code == to_unit_wrapper.unit_code:
            return initial_value_wrapper.value

        celsius_value = self._to_celsius(initial_value_wrapper.value, from_unit_wrapper.unit_code)
        target_value = self._from_celsius(celsius_value, to_unit_wrapper.unit_code)
        return target_value

    def _to_celsius(self, value, unit):
        if unit == 'C':
            return value
        elif unit == 'F':
            return (value - 32) * 5/9
        elif unit == 'K':
            return value - 273.15

    def _from_celsius(self, value, unit):
        if unit == 'C':
            return value
        elif unit == 'F':
            return (value * 9/5) + 32
        elif unit == 'K':
            return value + 273.15

