class CharacterRequirement:
    def __init__(self, check_func, description):
        self.check_func = check_func
        self.description = description

    def is_met(self, password_string):
        return self.check_func(password_string)

class PasswordLength:
    def __init__(self, min_length):
        self.min_length = min_length

    def is_met(self, password_string):
        return len(password_string) >= self.min_length

class StrengthLevel:
    def __init__(self, level_name, min_requirements_met):
        self.level_name = level_name
        self.min_requirements_met = min_requirements_met

class PasswordEvaluator:
    def evaluate(self, password_string, strength_criteria):
        return strength_criteria.get_level(password_string)

class PasswordStrengthCriteria:
    def __init__(self):
        self.has_upper = CharacterRequirement(lambda s: any(c.isupper() for c in s), "uppercase")
        self.has_lower = CharacterRequirement(lambda s: any(c.islower() for c in s), "lowercase")
        self.has_digit = CharacterRequirement(lambda s: any(c.isdigit() for c in s), "digit")
        self.is_long = PasswordLength(8)
        self.is_medium_long = PasswordLength(6)

        self.all_char_reqs = [self.has_upper, self.has_lower, self.has_digit]

        self.strong_level = StrengthLevel('Strong', 3)
        self.medium_level = StrengthLevel('Medium', 2)

    def get_level(self, password_string):
        char_reqs_met_count = sum(req.is_met(password_string) for req in self.all_char_reqs)

        if self.is_long.is_met(password_string) and char_reqs_met_count == self.strong_level.min_requirements_met:
            return self.strong_level.level_name
        elif self.is_medium_long.is_met(password_string) and char_reqs_met_count >= self.medium_level.min_requirements_met:
            return self.medium_level.level_name
        else:
            return 'Weak'

def check_password_strength(password):
    evaluator = PasswordEvaluator()
    criteria = PasswordStrengthCriteria()
    return evaluator.evaluate(password, criteria)

