        self.has_digit = character_requirement(lambda s: any(c.isdigit() for c in s), "digit")
        self.is_long = password_length(8)
        self.is_medium_long = password_length(6)

        self.all_char_reqs = [self.has_upper, self.has_lower, self.has_digit]

        self.strong_level = strength_level('Strong', 3)
        self.medium_level = strength_level('Medium', 2)

    def get_level(self, password_string):
        char_reqs_met_count = sum(req.is_met(password_string) for req in self.all_char_reqs)

        if self.is_long.is_met(password_string) and char_reqs_met_count == self.strong_level.min_requirements_met:
            return self.strong_level.level_name
        elif self.is_medium_long.is_met(password_string) and char_reqs_met_count >= self.medium_level.min_requirements_met:
            return self.medium_level.level_name
        else:
            return 'Weak'

def check_password_strength(password):
    evaluator = password_evaluator()
    criteria = password_strength_criteria()
    return evaluator.evaluate(password, criteria)

