class NumberChecker:
    def __init__(self, number_value):
        self.number_value = number_value

    def is_less_than_two(self):
        return self.number_value < 2

class DivisorFinder:
    def __init__(self, target_number):
        self.target_number = target_number

    def find_potential_divisors(self):
        return range(2, int(self.target_number**0.5) + 1)

class PrimalityTestResult:
    def __init__(self, is_prime_status):
        self.is_prime_status = is_prime_status

class DivisibilityChecker:
    def __init__(self, dividend, divisor):
        self.dividend = dividend
        self.divisor = divisor

    def is_perfectly_divisible(self):
        return self.dividend % self.divisor == 0

class PrimeNumberEvaluator:
    def evaluate(self, number_to_check):
        number_instance = NumberChecker(number_to_check)
        if number_instance.is_less_than_two():
            return PrimalityTestResult(False).is_prime_status

        if number_to_check == 2:
            return PrimalityTestResult(True).is_prime_status

        finder = DivisorFinder(number_to_check)
        for divisor in finder.find_potential_divisors():
            checker = DivisibilityChecker(number_to_check, divisor)
            if checker.is_perfectly_divisible():
                return PrimalityTestResult(False).is_prime_status
        return PrimalityTestResult(True).is_prime_status

def is_prime(n):
    evaluator = PrimeNumberEvaluator()
    return evaluator.evaluate(n)

